      - { id: alumno_fecha_nacimiento, etiqueta: "F. nacimiento:", tipo: fecha, privacidad: cuasi, guia: "Fecha de nacimiento", vinculo: alumno.fecha_nacimiento, validacion: fecha_nacimiento, hueco: { tipo: marcador, ancla: alumno_fecha_nacimiento } }
