      - { id: padre_nombre, etiqueta: "Padre/tutor legal:", tipo: texto, privacidad: identificador, guia: "Padre o tutor legal", vinculo: representantes.padre_tutor.nombre_completo, hueco: { tipo: marcador, ancla: padre_nombre } }
      - { id: madre_nombre, etiqueta: "Madre/tutora legal:", tipo: texto, privacidad: identificador, guia: "Madre o tutora legal", vinculo: representantes.madre_tutora.nombre_completo, hueco: { tipo: marcador, ancla: madre_nombre } }
      - { id: alumno_domicilio, etiqueta: "Domicilio:", tipo: texto, privacidad: identificador, guia: "Domicilio", vinculo: alumno.domicilio, hueco: { tipo: marcador, ancla: alumno_domicilio } }
      - { id: alumno_localidad, etiqueta: "Localidad:", tipo: texto, privacidad: identificador, guia: "Localidad", vinculo: alumno.localidad_residencia, hueco: { tipo: marcador, ancla: alumno_localidad } }
