      - { id: recursos_centro_otros, etiqueta: "Recursos Personales · Otros:", tipo: texto, privacidad: contenido, hueco: { tipo: marcador, ancla: recursos_centro_otros } }
      - { id: intervencion_externa, etiqueta: "Intervención fuera del centro (público o privado):", tipo: si_no, privacidad: contenido, ayuda_breve: "Medidas Complementarias recibidas por el alumno /a:", hueco: { tipo: casilla_w14, ancla: ext } }
      - { id: intervencion_externa_especificar, etiqueta: "Intervención fuera del centro · Sí, Especificar:", tipo: texto, privacidad: contenido, visible_si: "intervencion_externa == true", hueco: { tipo: marcador, ancla: intervencion_externa_especificar } }
