      - { id: otras_razones, etiqueta: "Otras razones que justifiquen la intervención socioeducativa y familiar:", tipo: parrafo, privacidad: contenido, hueco: { tipo: marcador, ancla: otras_razones } }
      - { id: actuaciones_previas, etiqueta: "Actuaciones previas realizadas (Medidas organizativas del aula, apoyos, economía de fichas, reuniones con la familia", tipo: parrafo, privacidad: contenido, hueco: { tipo: marcador, ancla: actuaciones_previas } }
      - { id: caracteristicas_alumno, etiqueta: "Características del alumno/a (Autonomía e independencia personal, habilidades de relación, conducta, desarrollo psicoemocional, madurativo…)", tipo: parrafo, privacidad: contenido, hueco: { tipo: marcador, ancla: caracteristicas_alumno } }
      - { id: dinamica_escolar, etiqueta: "Dinámica escolar del alumno/a (Con sus compañeros, con el profesorado, rendimiento escolar…)", tipo: parrafo, privacidad: contenido, hueco: { tipo: marcador, ancla: dinamica_escolar } }

