      - { id: recursos_personales_centro, ayuda_breve: "Recursos generales y especializados para la atención al alumnado con necesidades específicas de apoyo educativo", etiqueta: "Recursos personales:", tipo: parrafo, privacidad: contenido, hueco: { tipo: marcador, ancla: recursos_personales_centro } }
