      - { id: alumno_apellidos, etiqueta: "Apellidos:", tipo: texto, privacidad: identificador, guia: "Apellidos", vinculo: "alumno.apellidos", obligatorio: true, hueco: { tipo: marcador, ancla: alumno_apellidos } }
      - { id: alumno_nombre, etiqueta: "Nombre:", tipo: texto, privacidad: identificador, guia: "Nombre", vinculo: "alumno.nombre", obligatorio: true, hueco: { tipo: marcador, ancla: alumno_nombre } }
      - { id: centro_nombre, etiqueta: "Centro Educativo:", tipo: texto, privacidad: cuasi, guia: "Centro", vinculo: "centro.nombre", hueco: { tipo: marcador, ancla: centro_nombre } }
      - { id: centro_direccion, etiqueta: "Dirección:", tipo: texto, privacidad: cuasi, guia: "Dirección", vinculo: "centro.direccion", hueco: { tipo: marcador, ancla: centro_direccion } }
