      - { id: coord_programa_familia, etiqueta: "Programa de Familia", tipo: parrafo, privacidad: contenido, hueco: { tipo: marcador, ancla: coord_programa_familia } }
      - { id: coord_servicios_educativos, etiqueta: "Servicios educativos (UPE, Inspección equipos específicos...)", tipo: parrafo, privacidad: contenido, hueco: { tipo: marcador, ancla: coord_servicios_educativos } }
      - { id: coord_sanitarios, etiqueta: "Servicios sanitarios (Pediatra, SMI...)", tipo: parrafo, privacidad: contenido, hueco: { tipo: marcador, ancla: coord_sanitarios } }
